function evidence = f90_xmed04_extract_candidate_evidence(modelPath, outDir)
%f90_xmed04_extract_candidate_evidence Candidate bound port-graph extraction entry.
arguments
    modelPath (1,1) string = ""
    outDir (1,1) string = ""
end

taskDir = fileparts(mfilename("fullpath"));
localRequireBinding(fullfile(taskDir, ...
    "f90_xmed04_extract_evidence.m"), ...
    "present");
localRequireBinding(fullfile(taskDir, ...
    "f90_xmed04_structure_policy_core.py"), ...
    "present");

evidence = f90_xmed04_extract_evidence(modelPath, outDir);
assert(isfield(evidence, "candidate_evidence_ready") && ...
    logical(evidence.candidate_evidence_ready), ...
    "SimuVerity:F90:XMED04:EvidenceContract", ...
    "Candidate evaluator did not return candidate COMPATIBILITY evidence.");
assert(isfield(evidence, "current_evidence_reusable_as") && ...
    ~logical(evidence.current_evidence_reusable_as), ...
    "SimuVerity:F90:XMED04:HistoricalEvidenceBoundary", ...
    "Historical GROUP_SCORING evidence cannot be relabeled as COMPATIBILITY evidence.");
assert(isfield(evidence, "extraction_only") && ...
    logical(evidence.extraction_only) && ...
    isfield(evidence, "score_fields_present") && ...
    ~logical(evidence.score_fields_present), ...
    "SimuVerity:F90:XMED04:ExtractionOnly", ...
    "Candidate evaluator must not aggregate score fields.");
assert(isfield(evidence, "candidate_binding_preserved_by_current_audit") && ...
    logical(evidence.candidate_binding_preserved_by_current_audit), ...
    "SimuVerity:F90:XMED04:CandidateBinding", ...
    "The COMPATIBILITY audit must preserve the sealed candidate binding.");
end

function localRequireBinding(pathValue, expected)
assert(isfile(pathValue) && localFilePresence(pathValue) == lower(string(expected)), ...
    "SimuVerity:F90:XMED04:DependencyBinding", ...
    "A declared COMPATIBILITY evaluator dependency is missing or changed.");
end

function value = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
value = "present";
end

